        raise ValueError("invalid")
    return unit_cents * quantity - discount_pct

def shipping_cents(subtotal_cents):
    if subtotal_cents < 0:
        raise ValueError("invalid")
    if subtotal_cents > 5000:
        return 0
    return 599

